type Plugin = (ctx: any) => void;
class PluginHost {
  private plugins: Plugin[] = [];
  register(p: Plugin) { this.plugins.push(p); }
  start(ctx: any) { this.plugins.forEach(p => p(ctx)); }
}

// Version A: host invokes simple callback plugins
type Plugin = (ctx: any) => void;
class Host {
  private plugins: Plugin[] = [];
  register(p: Plugin) { this.plugins.push(p); }
  start(ctx: any) { this.plugins.forEach(p => p(ctx)); }
}

// Version B: plugins receive host and pull services themselves
interface PluginB { run(host: Host): void; }
class HostV2 {
  private plugins: PluginB[] = [];
  register(p: PluginB) { this.plugins.push(p); }
  start() { this.plugins.forEach(p => p.run(this)); }
}
